def solve():
    points = [(x, y, z) for x in range(3) for y in range(3) for z in range(3)]
    directions = []
    for x in range(3):
        for y in range(3):
            for z in range(3):
                if (x, y, z) == (0, 0, 0):
                    continue
                # Normalize direction: first non-zero coordinate must be 1
                if x != 0:
                    if x == 2: continue
                elif y != 0:
                    if y == 2: continue
                elif z != 0:
                    if z == 2: continue
                directions.append((x, y, z))

    assert len(directions) == 13

    weeks = []
    for d in directions[:6]:
        # Form parallel class for direction d
        # Two points p1, p2 are on the same line if p1 - p2 is a multiple of d
        groups = []
        used = set()
        for p in points:
            if p in used:
                continue
            line = []
            for t in range(3):
                pt = ((p[0] + t*d[0]) % 3, (p[1] + t*d[1]) % 3, (p[2] + t*d[2]) % 3)
                line.append(pt)
                used.add(pt)
            groups.append(line)
        weeks.append(groups)

    # Convert to the required format
    # entry w*27 + p gives the group (in 0..8) of golfer p in week w
    point_to_idx = {p: i for i, p in enumerate(points)}

    result = []
    for w in range(6):
        week_groups = weeks[w]
        golfer_to_group = [0] * 27
        for g_idx, group in enumerate(week_groups):
            for p in group:
                golfer_to_group[point_to_idx[p]] = g_idx
        result.extend(golfer_to_group)

    print(result)

solve()

def verify(result):
    weeks = 6
    golfers = 27
    groups_per_week = 9

    pairs = set()
    for w in range(weeks):
        groups = [[] for _ in range(groups_per_week)]
        for p in range(golfers):
            g = result[w * golfers + p]
            groups[g].append(p)

        for g in groups:
            assert len(g) == 3, f"Group {g} does not have 3 players"
            for i in range(len(g)):
                for j in range(i + 1, len(g)):
                    pair = tuple(sorted([g[i], g[j]]))
                    assert pair not in pairs, f"Pair {pair} repeated"
                    pairs.add(pair)
    print("Valid!")

